// Constants
const width = 800;
const height = 600;
const etfRadius = 20;
const minRadius = 15;
const maxRadius = 60;

// Set up SVG
const svg = d3.select("#bubble-chart")
    .append("svg")
    .attr("width", width)
    .attr("height", height)
    .attr("viewBox", [0, 0, width, height]);

const tooltip = d3.select("#tooltip");

// Load data
d3.csv("data/stock-descriptions.csv").then(data => {
    // Data processing
    data.forEach(d => {
        d.marketCap = d.marketCap ? parseFloat(d.marketCap) : null;
        d.isETF = d.sector === "ETF";
    });

    // Take only the first 50 stocks as requested (or all if less than 50)
    const stocks = data.slice(0, 50);

    // Sectors for clustering
    const sectors = Array.from(new Set(stocks.map(d => d.sector))).sort();

    // Color scale
    const color = d3.scaleOrdinal()
        .domain(sectors)
        .range(d3.schemeCategory10);

    // Radius scale for market cap
    const marketCaps = stocks.filter(d => !d.isETF).map(d => d.marketCap);
    const radiusScale = d3.scaleSqrt()
        .domain([d3.min(marketCaps), d3.max(marketCaps)])
        .range([minRadius, maxRadius]);

    stocks.forEach(d => {
        d.radius = d.isETF ? etfRadius : radiusScale(d.marketCap);
    });

    // Define cluster centers
    const clusterCenters = {};
    const angleStep = (2 * Math.PI) / sectors.length;
    const clusterRadius = 150;
    sectors.forEach((sector, i) => {
        clusterCenters[sector] = {
            x: width / 2 + Math.cos(i * angleStep) * clusterRadius,
            y: height / 2 + Math.sin(i * angleStep) * clusterRadius
        };
    });

    // Force simulation
    const simulation = d3.forceSimulation(stocks)
        .force("x", d3.forceX(d => clusterCenters[d.sector].x).strength(0.15))
        .force("y", d3.forceY(d => clusterCenters[d.sector].y).strength(0.15))
        .force("collide", d3.forceCollide(d => d.radius + 2))
        .force("center", d3.forceCenter(width / 2, height / 2))
        .stop();

    // Run simulation for fixed number of ticks for determinism
    for (let i = 0; i < 300; ++i) simulation.tick();

    // Draw bubbles
    const node = svg.append("g")
        .selectAll(".node")
        .data(stocks)
        .join("g")
        .attr("class", "node")
        .attr("transform", d => `translate(${d.x}, ${d.y})`)
        .on("click", (event, d) => {
            selectStock(d.ticker);
        })
        .on("mouseover", (event, d) => {
            if (!d.isETF) {
                tooltip.classed("visible", true)
                    .html(`<strong>${d.ticker}</strong><br/>
                           Name: ${d['full name']}<br/>
                           Sector: ${d.sector}<br/>
                           Market Cap: ${formatMarketCap(d.marketCap)}`)
                    .style("left", (event.pageX + 10) + "px")
                    .style("top", (event.pageY - 10) + "px");
            }
        })
        .on("mousemove", (event) => {
            tooltip.style("left", (event.pageX + 10) + "px")
                .style("top", (event.pageY - 10) + "px");
        })
        .on("mouseout", () => {
            tooltip.classed("visible", false);
        });

    node.append("circle")
        .attr("class", d => `bubble bubble-${d.ticker}`)
        .attr("r", d => d.radius)
        .attr("fill", d => color(d.sector));

    node.append("text")
        .attr("class", "label")
        .attr("dy", ".3em")
        .text(d => d.ticker);

    // Create Legend
    const legendContainer = d3.select("#legend-container");
    sectors.forEach(sector => {
        const item = legendContainer.append("div").attr("class", "legend-item");
        item.append("div")
            .attr("class", "legend-color")
            .style("background-color", color(sector));
        item.append("span").text(sector);
    });

    // Create Table
    const tbody = d3.select("#stock-table tbody");
    const rows = tbody.selectAll("tr")
        .data(stocks)
        .join("tr")
        .attr("id", d => `row-${d.ticker}`)
        .on("click", (event, d) => {
            selectStock(d.ticker);
        });

    rows.append("td").text(d => d.ticker);
    rows.append("td").text(d => d['full name']);
    rows.append("td").text(d => d.sector);
    rows.append("td").text(d => formatMarketCap(d.marketCap));

    // Selection function
    function selectStock(ticker) {
        // Highlight bubble
        d3.selectAll(".bubble").classed("highlighted", false);
        d3.select(`.bubble-${ticker}`).classed("highlighted", true);

        // Highlight row
        d3.selectAll("#stock-table tr").classed("highlighted", false);
        const selectedRow = d3.select(`#row-${ticker}`);
        selectedRow.classed("highlighted", true);

        // Scroll row into view
        selectedRow.node().scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
});

function formatMarketCap(val) {
    if (val === null || val === undefined || isNaN(val)) return "N/A";
    if (val >= 1e12) return (val / 1e12).toFixed(2) + "T";
    if (val >= 1e9) return (val / 1e9).toFixed(2) + "B";
    if (val >= 1e6) return (val / 1e6).toFixed(2) + "M";
    return val.toLocaleString();
}

